# -*- coding: utf-8 -*-
"""按36页设计稿渲染演示图：HTML/CSS/SVG -> Playwright Chromium -> 3840x2160 PNG -> PDF"""
import os, math, html
from playwright.sync_api import sync_playwright

OUT = "/workspace/outputs"
os.makedirs(OUT, exist_ok=True)

E = html.escape

CSS = """
*{margin:0;padding:0;box-sizing:border-box;}
body{width:1920px;height:1080px;}
.page{width:1920px;height:1080px;background:#FAFBFD;color:#0E2A5C;
 font-family:'Noto Sans CJK SC','Noto Sans SC',sans-serif;position:relative;overflow:hidden;
 padding:76px 110px;display:flex;flex-direction:column;}
.bg-grid{position:absolute;inset:0;
 background-image:linear-gradient(rgba(30,111,217,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(30,111,217,.045) 1px,transparent 1px);
 background-size:96px 96px;}
.blob{position:absolute;border-radius:50%;}
.blob.tr{right:-230px;top:-230px;width:660px;height:660px;
 background:radial-gradient(circle at 40% 40%,rgba(30,111,217,.12),rgba(18,181,203,.05) 60%,transparent 72%);}
.blob.bl{left:-270px;bottom:-270px;width:640px;height:640px;
 background:radial-gradient(circle at 60% 40%,rgba(18,181,203,.10),transparent 70%);}
.z{position:relative;z-index:2;}
.kicker{display:inline-flex;align-items:center;gap:16px;font-size:25px;letter-spacing:7px;color:#1E6FD9;font-weight:600;}
.kicker::before{content:'';width:48px;height:7px;border-radius:4px;background:linear-gradient(90deg,#1E6FD9,#12B5CB);}
.title{font-size:58px;font-weight:800;color:#0B2A5B;margin-top:20px;line-height:1.28;}
.sub{font-size:29px;color:#41608E;margin-top:14px;line-height:1.55;font-weight:400;}
.content{flex:1;display:flex;align-items:center;justify-content:center;position:relative;z-index:2;}
.footer{position:absolute;left:110px;right:110px;bottom:50px;height:8px;border-radius:4px;
 background:linear-gradient(90deg,#1E6FD9,#12B5CB,rgba(18,181,203,0));opacity:.5;}
.grad{background:linear-gradient(90deg,#1E6FD9,#12B5CB);-webkit-background-clip:text;background-clip:text;color:transparent;}
.chip{display:inline-flex;align-items:center;gap:12px;background:#fff;border:2px solid #D7E3F4;border-radius:14px;
 padding:14px 26px;font-size:27px;color:#173E77;font-weight:600;box-shadow:0 4px 14px rgba(21,70,160,.06);}
.chip.on{border-color:#1E6FD9;background:linear-gradient(120deg,rgba(30,111,217,.10),rgba(18,181,203,.10));color:#0E4FA8;}
.dot{width:12px;height:12px;border-radius:50%;background:linear-gradient(135deg,#1E6FD9,#12B5CB);flex:none;}
.arw{font-size:44px;color:#1E6FD9;font-weight:700;padding:0 8px;}
.note{font-size:25px;color:#5B759E;}
/* radial */
.radial{position:relative;}
.rlines{position:absolute;left:0;top:0;}
.rline{stroke:#9CC4E8;stroke-width:2.5;}
.rcenter{position:absolute;width:220px;height:220px;border-radius:50%;
 background:linear-gradient(135deg,#1E6FD9,#12B5CB);color:#fff;display:flex;align-items:center;justify-content:center;
 font-size:31px;font-weight:800;text-align:center;box-shadow:0 14px 34px rgba(30,111,217,.30);line-height:1.35;padding:18px;}
.rnode{position:absolute;width:240px;height:96px;background:#fff;border:2px solid #D7E3F4;border-radius:16px;
 display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:#12406F;
 box-shadow:0 6px 18px rgba(21,70,160,.08);}
/* venn */
.vwrap{position:relative;}
.vc{position:absolute;border-radius:50%;mix-blend-mode:multiply;}
.vlabel{position:absolute;font-size:27px;font-weight:700;color:#12406F;display:flex;align-items:center;gap:10px;}
.vcenter{position:absolute;transform:translate(-50%,-50%);background:#fff;border:3px solid #1E6FD9;border-radius:999px;
 padding:16px 34px;font-size:29px;font-weight:800;color:#0E4FA8;box-shadow:0 10px 26px rgba(30,111,217,.20);white-space:nowrap;}
/* rows */
.row3{display:flex;align-items:center;gap:34px;margin:26px 0;}
.row3 .lft{width:430px;justify-content:center;}
.row3 .rgt{width:560px;justify-content:center;}
/* compare */
.cmp{display:flex;gap:46px;align-items:stretch;width:100%;}
.panel{flex:1;background:#fff;border:2px solid #D7E3F4;border-radius:22px;padding:34px 40px;
 box-shadow:0 10px 28px rgba(21,70,160,.07);display:flex;flex-direction:column;}
.panel h3{font-size:31px;font-weight:800;color:#0E4FA8;margin-bottom:20px;display:flex;align-items:center;gap:12px;}
.gates{display:flex;flex-wrap:wrap;gap:14px;}
.gate{background:#F1F6FC;border:1.5px solid #CBDCEF;border-radius:10px;padding:10px 20px;font-size:24px;color:#2A5286;font-weight:600;}
.kws{display:flex;gap:18px;justify-content:center;margin-top:38px;}
.kw{background:linear-gradient(120deg,rgba(30,111,217,.09),rgba(18,181,203,.09));border:1.5px solid #BBD8EE;
 border-radius:999px;padding:12px 30px;font-size:25px;font-weight:700;color:#0E4FA8;}
/* formula */
.formula{display:flex;align-items:center;gap:26px;}
.fcard{width:290px;height:210px;border-radius:22px;background:linear-gradient(150deg,#1E6FD9,#12B5CB);color:#fff;
 display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;font-size:34px;font-weight:800;
 box-shadow:0 16px 36px rgba(30,111,217,.28);text-align:center;padding:18px;}
.fop{font-size:64px;color:#7A94BB;font-weight:300;}
.fres{width:330px;height:250px;border-radius:26px;border:3px solid #1E6FD9;background:#fff;color:#0E4FA8;
 display:flex;align-items:center;justify-content:center;font-size:42px;font-weight:800;
 box-shadow:0 16px 40px rgba(30,111,217,.18);}
/* funnel */
.funnel{display:flex;flex-direction:column;align-items:center;gap:10px;}
.fstep{height:86px;border-radius:14px;display:flex;align-items:center;justify-content:center;
 color:#fff;font-size:30px;font-weight:800;background:linear-gradient(90deg,#1E6FD9,#12B5CB);box-shadow:0 8px 20px rgba(30,111,217,.18);}
/* chain */
.chain{display:flex;flex-direction:column;align-items:center;gap:6px;}
.cstep{background:#fff;border:2px solid #D7E3F4;border-radius:16px;padding:18px 44px;font-size:30px;font-weight:700;
 color:#12406F;box-shadow:0 6px 16px rgba(21,70,160,.07);display:flex;align-items:center;gap:16px;}
.cstep.last{background:linear-gradient(120deg,#1E6FD9,#12B5CB);color:#fff;border:none;}
.cdown{font-size:36px;color:#12B5CB;line-height:1;}
/* grid4 */
.g4{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:34px;width:1420px;}
.g4 .card{background:#fff;border:2px solid #D7E3F4;border-radius:20px;padding:34px 38px;
 box-shadow:0 8px 22px rgba(21,70,160,.07);display:flex;flex-direction:column;gap:12px;min-height:200px;}
.g4 .card b{font-size:31px;color:#0E4FA8;}
.g4 .card span{font-size:25px;color:#5B759E;line-height:1.5;}
.g4 .hub{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:250px;height:250px;border-radius:50%;
 background:linear-gradient(135deg,#1E6FD9,#12B5CB);color:#fff;display:flex;align-items:center;justify-content:center;
 font-size:32px;font-weight:800;box-shadow:0 0 0 12px rgba(250,251,253,1),0 18px 40px rgba(30,111,217,.30);text-align:center;line-height:1.4;padding:24px;}
/* matrix */
.mx{position:relative;width:1000px;height:600px;}
.mxgrid{position:absolute;inset:40px 0 70px 90px;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:6px;}
.mzone{border-radius:14px;background:#F1F6FC;border:1.5px solid #D7E3F4;display:flex;align-items:center;justify-content:center;
 font-size:29px;font-weight:700;color:#41608E;}
.mzone.hot{background:linear-gradient(130deg,rgba(30,111,217,.85),rgba(18,181,203,.85));color:#fff;box-shadow:0 14px 30px rgba(30,111,217,.30);}
.maxis-y{position:absolute;left:8px;top:40px;bottom:70px;width:60px;display:flex;align-items:center;justify-content:center;}
.maxis-y span{transform:rotate(-90deg);white-space:nowrap;font-size:26px;color:#2A5286;font-weight:700;letter-spacing:4px;}
.maxis-x{position:absolute;left:90px;right:0;bottom:16px;text-align:center;font-size:26px;color:#2A5286;font-weight:700;letter-spacing:4px;}
.mdot{position:absolute;width:22px;height:22px;border-radius:50%;background:#0E4FA8;border:3px solid #fff;box-shadow:0 4px 10px rgba(14,79,168,.4);}
/* stairs */
.stairs{display:flex;align-items:flex-end;gap:36px;}
.stair{width:420px;border-radius:20px 20px 0 0;background:#fff;border:2px solid #D7E3F4;border-bottom:6px solid #1E6FD9;
 padding:34px 36px;box-shadow:0 10px 26px rgba(21,70,160,.08);display:flex;flex-direction:column;gap:12px;}
.stair.hot{background:linear-gradient(150deg,#1E6FD9,#12B5CB);border:none;border-bottom:6px solid #0E4FA8;color:#fff;}
.stair.hot .sd{color:rgba(255,255,255,.88);}
.stair b{font-size:34px;color:#0E4FA8;}
.stair.hot b{color:#fff;}
.stair .sd{font-size:25px;color:#5B759E;line-height:1.5;}
/* pyramid */
.pyr{display:flex;flex-direction:column;align-items:center;gap:8px;}
.ply{height:88px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:28px;font-weight:800;}
/* network scene */
.scene{display:flex;gap:70px;align-items:center;width:100%;}
.tags{display:flex;flex-direction:column;gap:20px;width:560px;}
.tags .chip{font-size:28px;}
/* timeline */
.tl{position:relative;width:1560px;height:420px;}
.tlline{position:absolute;left:30px;right:30px;top:200px;height:10px;border-radius:5px;background:linear-gradient(90deg,#1E6FD9,#12B5CB);}
.tlitem{position:absolute;width:460px;}
.tlitem .card{background:#fff;border:2px solid #D7E3F4;border-radius:18px;padding:26px 30px;box-shadow:0 8px 22px rgba(21,70,160,.08);}
.tlitem .card b{font-size:32px;color:#0E4FA8;display:block;margin-bottom:8px;}
.tlitem .card span{font-size:25px;color:#5B759E;line-height:1.5;}
.tldot{position:absolute;top:193px;width:24px;height:24px;border-radius:50%;background:#fff;border:6px solid #1E6FD9;}
/* loop */
.loopbox{position:relative;}
.lnode{position:absolute;width:250px;height:92px;border-radius:16px;background:#fff;border:2px solid #D7E3F4;
 display:flex;align-items:center;justify-content:center;font-size:27px;font-weight:700;color:#12406F;box-shadow:0 6px 16px rgba(21,70,160,.08);}
.lcenter{position:absolute;transform:translate(-50%,-50%);font-size:30px;font-weight:800;color:#0E4FA8;
 background:linear-gradient(120deg,rgba(30,111,217,.10),rgba(18,181,203,.10));border:3px solid #1E6FD9;border-radius:999px;padding:16px 36px;}
/* concentric */
.conc{position:relative;width:640px;height:640px;border-radius:50%;background:#EAF2FB;border:2px solid #C9DCF2;
 display:flex;align-items:center;justify-content:center;}
.conc .mid{width:440px;height:440px;border-radius:50%;background:#D8E9F9;border:2px solid #AFCDEB;display:flex;align-items:center;justify-content:center;}
.conc .core{width:250px;height:250px;border-radius:50%;background:linear-gradient(135deg,#1E6FD9,#12B5CB);color:#fff;
 display:flex;align-items:center;justify-content:center;font-size:29px;font-weight:800;text-align:center;padding:20px;box-shadow:0 16px 36px rgba(30,111,217,.30);}
.conc .ring-label{position:absolute;left:50%;transform:translateX(-50%);font-size:25px;font-weight:700;color:#2A5286;white-space:nowrap;}
/* stack */
.stack{display:flex;gap:30px;align-items:stretch;width:1480px;}
.layers{flex:1;display:flex;flex-direction:column;gap:20px;}
.layer{border-radius:16px;padding:24px 34px;display:flex;align-items:center;gap:24px;}
.layer b{font-size:28px;flex:none;}
.layer span{font-size:24px;}
.side{width:130px;border-radius:16px;background:linear-gradient(180deg,#1E6FD9,#12B5CB);color:#fff;display:flex;
 align-items:center;justify-content:center;font-size:26px;font-weight:800;letter-spacing:6px;writing-mode:vertical-rl;text-orientation:upright;}
/* path7 */
.p7{display:flex;gap:20px;width:100%;}
.p7 .pc{flex:1;background:#fff;border:2px solid #D7E3F4;border-radius:16px;padding:24px 18px;text-align:center;
 display:flex;flex-direction:column;align-items:center;gap:14px;box-shadow:0 6px 16px rgba(21,70,160,.06);}
.p7 .pc .warn{width:56px;height:56px;border-radius:50%;border:3px solid #E8B93E;display:flex;align-items:center;justify-content:center;
 color:#C99A16;font-size:32px;font-weight:800;background:#FDF6E3;}
.p7 .pc span{font-size:24px;font-weight:700;color:#2A5286;line-height:1.45;}
.pgoal{margin-top:34px;display:flex;justify-content:flex-end;}
/* scorecard */n
.score{display:flex;gap:60px;align-items:center;width:100%;}
.qs{display:flex;flex-direction:column;gap:22px;width:980px;}
.q{display:flex;align-items:center;gap:24px;background:#fff;border:2px solid #D7E3F4;border-radius:14px;padding:18px 26px;}
