.state{display:flex;flex-direction:column;align-items:center;gap:34px;text-align:center;}
.state .big{font-size:66px;font-weight:800;color:#0B2A5B;line-height:1.5;}
.state .big em{font-style:normal;}
.motif{margin-top:10px;}
