 <div class="lcenter" style="left:{cx}px;top:{cy}px">最小闭环</div>
</div></div>'''))

# ---- 32 三层边界 ----
docs.append(shell(head(P5, '自研、采购还是合作') + f'''
<div class="content z" style="gap:80px">
 <div class="conc">
  <div class="ring-label" style="top:36px">外层 · 通用能力：采购（模型 · 会议助手 · 办公工具）</div>
  <div class="mid"><div class="ring-label" style="top:56px">中层 · 行业流程：联合开发</div>
   <div class="core">核心壁垒<br/>自己掌握<br/><span style="font-size:20px;font-weight:500">数据 · 工艺知识 · 客户</span></div>
  </div>
 </div>
 <div style="max-width:640px">
  <div class="big z" style="font-size:44px;font-weight:800;color:#0B2A5B;line-height:1.7">模型不一定属于你<br/>但<span class="grad">数据、流程、知识和客户</span>必须属于你</div>
 </div>
</div>'''))

# ---- 33 最小基础设施 ----
lay33 = [('业务工作流', '研发 · 销售 · 生产 · 管理', '#1E6FD9,#12B5CB'),
         ('权限与安全 · 专业知识 · 模型能力', '知识库与模型服务', '#5A8AD6,#3FB6CD'),
         ('数据与文档 · 业务系统', '数据、文档与系统底座', '#8FB0DE,#7BC8D8')]
lay33_html = ''.join(
    f'<div class="layer" style="background:linear-gradient(90deg,{g});color:#fff"><b>{E(a)}</b><span style="opacity:.92">{E(b)}</span></div>'
    for a, b, g in lay33)
docs.append(shell(head(P5, 'AI原生的最小基础设施') +
    f'<div class="content z"><div class="stack"><div class="layers">{lay33_html}</div><div class="side">评价 · 反馈 · 审计 · 合规</div></div></div>'))

# ---- 34 七个误区 ----
m34 = ['追逐所有热门赛道', '把AI当成独立部门', '先买模型再找场景', '把Demo当成产品', '只算模型成本', '追求完全无人化', '只提效、不沉淀']
m34_html = ''.join(
    f'<div class="pc"><div class="warn">!</div><span>{E(t)}</span></div>' for t in m34)
docs.append(shell(head(P6, '七个常见误区') + f'''
<div class="content z"><div style="display:flex;flex-direction:column;width:100%;gap:40px">
 <div class="p7">{m34_html}</div>
 <div class="pgoal"><div class="chip on" style="font-size:29px;padding:18px 40px">正确方向：AI原生</div></div>
</div></div>'''))

# ---- 35 现场自测 ----
q35 = ['我们的客户痛点是否真实？', '我们是否拥有独特数据与资源？', '产品是否能够标准化复制？',
       'AI是否已经进入业务流程？', '每完成一个项目，系统是否会变得更聪明？']
q35_html = ''.join(
    f'<div class="q"><span>{E(t)}</span><div class="pills"><div class="pill">0</div><div class="pill">1</div><div class="pill">2</div></div></div>'
    for t in q35)
rungs = ['0—3 · 探索期', '4—6 · 场景验证期', '7—8 · 能力形成期', '9—10 · 平台化机会期']
rungs_html = ''.join(
    f'<div class="rung{"" if i else " dim"}" style="width:{360+i*90}px">{E(t)}</div>' for i, t in enumerate(rungs))
docs.append(shell(head(P6, '企业现场自测') +
    f'<div class="content z"><div class="score"><div class="qs">{q35_html}</div><div class="ladder">{rungs_html}</div></div></div>'))

# ---- 36 结束页 ----
tree_svg = '''
<svg width="640" height="560" viewBox="0 0 640 560">
 <defs><linearGradient id="tg" x1="0" y1="1" x2="0" y2="0">
  <stop offset="0" stop-color="#1E6FD9"/><stop offset="1" stop-color="#12B5CB"/></linearGradient></defs>
 <path d="M320 520 L320 260" stroke="url(#tg)" stroke-width="14" stroke-linecap="round"/>
 <path d="M320 360 C 240 320, 200 280, 170 230 M320 340 C 400 300, 440 260, 470 210 M320 300 C 280 260, 260 240, 250 200 M320 300 C 360 260, 390 240, 400 190" 
  stroke="url(#tg)" stroke-width="7" fill="none" stroke-linecap="round"/>
 <g fill="#12B5CB">
  <circle cx="170" cy="200" r="26" opacity=".85"/><circle cx="470" cy="180" r="30" opacity=".85"/>
  <circle cx="250" cy="170" r="22" opacity=".7"/><circle cx="400" cy="160" r="24" opacity=".75"/>
  <circle cx="320" cy="120" r="34" opacity=".95"/><circle cx="220" cy="250" r="16" opacity=".5"/>
  <circle cx="430" cy="250" r="16" opacity=".5"/>
 </g>
 <path d="M180 520 C 240 500, 400 500, 460 520" stroke="#9CC4E8" stroke-width="6" fill="none" stroke-linecap="round"/>
 <text x="320" y="548" font-family="Noto Sans CJK SC" font-size="21" font-weight="700" fill="#41608E" text-anchor="middle">根植真实产业 · 枝叶延伸未来市场</text>
</svg>'''
docs.append(shell(head(P6, '写在最后') + f'''
<div class="content z" style="gap:70px">
 <div class="state" style="align-items:flex-start;text-align:left">
  <div class="big" style="font-size:48px">别只追热门赛道，要寻找<span class="grad">结构性的供需错配</span></div>
  <div class="big" style="font-size:48px">别只问AI能做什么，要问<span class="grad">企业最稀缺的能力</span>是什么</div>
  <div class="big" style="font-size:48px">赛道红利给企业一个<span class="grad">窗口</span>，AI原生能力决定企业<span class="grad">能走多远</span></div>
 </div>
 {tree_svg}
</div>'''))

assert len(docs) == 36, len(docs)

# ---------------- render ----------------
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/usr/bin/chromium", args=["--no-sandbox"])
    ctx = b.new_context(viewport={"width": 1920, "height": 1080}, device_scale_factor=2)
    pg = ctx.new_page()
    for i, doc in enumerate(docs, 1):
        pg.set_content(doc)
        pg.wait_for_timeout(150)
        pg.screenshot(path=f"{OUT}/page_{i:02d}.png")
        print(f"page {i:02d} ok")
    b.close()
print("RENDER DONE")

