# ---------------- helpers ----------------

def head(kicker, title, sub=None):
    s = f'<div class="z"><div class="kicker">{E(kicker)}</div><div class="title">{title}</div>'
    if sub:
        s += f'<div class="sub">{sub}</div>'
    return s + '</div>'

def shell(body, extra=""):
    return ("<html><head><meta charset='utf-8'><style>" + CSS + extra +
            "</style></head><body><div class='page'><div class='bg-grid'></div>"
            "<div class='blob tr'></div><div class='blob bl'></div>"
            + body + "<div class='footer'></div></div></body></html>")

def radial(center_label, nodes, R=235, W=1560, H=620):
    cx, cy = W/2, H/2
    n = len(nodes)
    pts = []
    for k in range(n):
        ang = -math.pi/2 + k*2*math.pi/n
        pts.append((cx + R*math.cos(ang)*1.55, cy + R*math.sin(ang)))
    lines = "".join(f'<line x1="{cx:.0f}" y1="{cy:.0f}" x2="{x:.0f}" y2="{y:.0f}" class="rline"/>' for x, y in pts)
    svg = f'<svg class="rlines" width="{W}" height="{H}">{lines}</svg>'
    center = f'<div class="rcenter" style="left:{cx-110:.0f}px;top:{cy-110:.0f}px"><span>{E(center_label)}</span></div>'
    nodes_html = "".join(
        f'<div class="rnode" style="left:{x-120:.0f}px;top:{y-48:.0f}px">{E(l)}</div>' for (x, y), l in zip(pts, nodes))
    return f'<div class="radial" style="width:{W}px;height:{H}px">{svg}{center}{nodes_html}</div>'

