# ---- 31 最小闭环 ----
loop31 = ['资料进入', 'AI分析', '人工复核', '进入业务', '结果回流']
LW, LH, R = 900, 560, 200
cx, cy = LW/2, LH/2
pts31 = [(cx + R*math.cos(-math.pi/2 + k*2*math.pi/5), cy + R*math.sin(-math.pi/2 + k*2*math.pi/5)) for k in range(5)]
arcs = ""
for k in range(5):
    x1, y1 = pts31[k]
    x2, y2 = pts31[(k+1) % 5]
    mx, my = (x1+x2)/2, (y1+y2)/2
    vx, vy = mx-cx, my-cy
    nl = math.hypot(vx, vy)
    mx2, my2 = cx + vx/nl*(R+46), cy + vy/nl*(R+46)
    arcs += (f'<path d="M{x1:.0f} {y1:.0f} Q {mx2:.0f} {my2:.0f} {x2:.0f} {y2:.0f}" fill="none" stroke="#1E6FD9" stroke-width="4" opacity=".55"')
    arcs += f' marker-end="url(#ah)"/>'
nodes31 = ''.join(
    f'<div class="lnode" style="left:{x-125:.0f}px;top:{y-46:.0f}px">{E(t)}</div>' for (x, y), t in zip(pts31, loop31))
docs.append(shell(head(P5, '什么叫最小闭环') + f'''
<div class="content z"><div class="loopbox" style="width:{LW}px;height:{LH}px">
 <svg width="{LW}" height="{LH}" style="position:absolute;left:0;top:0">
